import React from 'react';

import { ThresholdBar } from '../../../core/components/threshold-bar/ThresholdBar.js';
import { transformThresholdsToMarkers } from '../../../core/functions/thresholds-to-markers.js';
import { TimeseriesThresholdPosition } from '../../../core/types/thresholds.js';
import {
  useCurrentDomainState,
  useSetState,
} from '../../hooks/store/selectors.js';
import { useTimeseriesFilteredThresholds } from '../../hooks/useTimeseriesFilteredThresholds.js';
import { useTimeseriesYFormatter } from '../../hooks/useTimeseriesYFormatter.js';
import { useYScales } from '../../hooks/useYScales.js';

interface TimeseriesThresholdBarProps {
  position: TimeseriesThresholdPosition;
  length: number;
}

export function TimeseriesThresholdBar(props: TimeseriesThresholdBarProps) {
  const { position, length } = props;

  const { left: leftThreshold, right: rightThreshold } =
    useTimeseriesFilteredThresholds();
  const { left, right } = useYScales();
  const currentDomain = useCurrentDomainState();
  const isChartWithoutZoom = !currentDomain;
  const [leftFormatter, rightFormatter] = useTimeseriesYFormatter();
  const setState = useSetState();

  const isFlipped = position !== 'left';

  const yScale = position === 'left' ? left : right;
  if (!yScale) {
    return null;
  }

  const thresholds = position === 'left' ? leftThreshold : rightThreshold;
  if (!thresholds || !thresholds.length) {
    return null;
  }

  const axisFormatter = position === 'left' ? leftFormatter : rightFormatter;

  const markers = transformThresholdsToMarkers(thresholds, position);

  const handleHover = (id: string | undefined) => {
    setState((prev) => ({
      ...prev,
      thresholds: {
        ...thresholds,
        hoveredThresholdId: id,
      },
    }));
  };

  return markers.length ? (
    <ThresholdBar
      scale={yScale.scale}
      markers={isChartWithoutZoom ? markers : []}
      length={length}
      layout="vertical"
      isFlipped={isFlipped}
      onHover={handleHover}
      formatter={axisFormatter}
    />
  ) : null;
}

TimeseriesThresholdBar['displayName'] = 'TimeseriesThresholdBar';
